Você pode criar uma função que primeiro organiza as fases distintas e depois aplica esse mapeamento em cada registro. Segue uma versão pronta para usar no GEE Console ou em Apps Script (com a biblioteca `ee` carregada/inicializada).

```javascript
/**
 * Adiciona o campo "faseNumber" em uma FeatureCollection ou Coleção.
 * Cada valor distinto de "fase" recebe um número consecutivo a partir de 1.
 * Registros sem fase válida recebem faseNumber = null.
 *
 * A ordenação é alfabética por padrão. Troque .sort() se precisar de outra ordem.
 *
 * @param {ee.FeatureCollection|ee.Collection} coll
 * @returns {ee.FeatureCollection|ee.Collection}
 */
function adicionarFaseNumber(coll) {
  // 1) Coleta as fases distintas, ignorando nulas/ausentes, e ordena alfabeticamente.
  var fases = coll.aggregate_array('fase')
    .filterNot(function(fase) {
      return fase == null || fase.isNull();
    })
    .distinct()
    .sort();

  // 2) Monta o mapeamento fase -> número.
  var dictFases = ee.Dictionary({});
  var contador = 1;

  fases.toArray().forEach(function(fase) {
    dictFases.set(fase, contador++);
  });

  // 3) Aplica o mapeamento em cada registro, preservando as demais propriedades.
  return coll.map(function(record) {
    var fase = record.get('fase');

    var numeroFinal = null;
    if (record.getPropertyIsValid('fase') && !fase.isNull()) {
      numeroFinal = dictFases.get(fase);
    }

    // Reconstrói o feature e define faseNumber.
    var featurinha = ee.Feature(record.array());
    featurinha.setProperty('faseNumber', numeroFinal);

    return featurinha;
  });
}
```

### Exemplo de uso

```javascript
// Suponha que TQ_NaoTitulados1 já tenha a propriedade "fase"
var resultado = adicionarFaseNumber(TQ_NaoTitulados1);

// Para conferir os primeiros registros
print(resultado.first().getProperties());
```

Um resultado possível seria algo como:

```json
{
  "fase": "CCDRU",
  "faseNumber": 1,
  ...
}
```

```json
{
  "fase": "DECRETO",
  "faseNumber": 2,
  ...
}
```

Se você quiser que registros **sem** a propriedade `fase` sejam excluídos, em vez de receberem `faseNumber: null`, faça um filtro antes de chamar a função.

